/// 0000-MAINLINE-CONTROL
fn p_0000_mainline_control(state: &mut ProgramState) {
    p_0100_initial_routine(state);
    p_pps_bdgt_neut_rate(state);
    p_0100_exit(state);
    p_1000_edit_the_bill_info(state);
    p_1000_exit(state);
    if state.pps_data_all.pps_rtc == 00 {
        p_1700_edit_drg_code(state);
        p_1700_exit(state);
        if state.pps_data_all.pps_rtc == 00 {
            p_1800_edit_ipps_drg_code(state);
            p_1800_exit(state);
        }
    }
    if state.pps_data_all.pps_rtc == 00 {
        p_2000_assemble_pps_variables(state);
        p_2000_exit(state);
        if state.pps_data_all.pps_rtc == 00 {
            p_3000_calc_payment(state);
            p_3000_exit(state);
            p_7000_calc_outlier(state);
            p_h_blend_pps(state);
            p_sentence(state);
            p_7000_exit(state);
            if state.pps_data_all.pps_rtc < 50 {
                p_8000_blend(state);
                p_8000_exit(state);
                p_9000_move_results(state);
                p_9000_exit(state);
                return;
            }
        }
    }
}

/// 0100-INITIAL-ROUTINE
fn p_0100_initial_routine(state: &mut ProgramState) {
    state.pps_data_all.pps_rtc = 0;
    state.pps_data_all.pps_data = Default::default();
    state.pps_data_all.pps_other_data = Default::default();
    state.pps_cbsa = Default::default();
    state.hold_pps_components = Default::default();
    state.pps_cbsa = FixedString::copy_from(&state.prov_new_hold.prov_newrec_hold2.p_new_geo_loc_cbsax);
    p_1900_apply_ssrfbn(state);
    p_1900_exit(state);
    if state.pps_data_all.pps_rtc != 00 {
        p_0100_exit(state); return;
    }
    // SKIP: unresolved ref
    // SKIP: unresolved ref
    state.pps_data_all.pps_other_data.pps_std_fed_rate = (39114.36).into();
    state.hold_pps_components.h_fixed_loss_amt = (22960.00).into();
}

/// PPS-BDGT-NEUT-RATE
fn p_pps_bdgt_neut_rate(state: &mut ProgramState) {
    state.hold_pps_components.h_ipps_capi_std_fed_rate = (424.17).into();
    state.hold_pps_components.h_ipps_capi_std_pr_rate = (198.77).into();
    state.hold_pps_components.h_nat_ipps_pmt_pct = (0.75).into();
    state.hold_pps_components.h_pr_ipps_pmt_pct = (0.25).into();
    if i64::from(state.hold_pps_components.h_ipps_wage_index) > 1i64 {
        state.hold_pps_components.h_ipps_nat_labor_shr = (3574.50).into();
        state.hold_pps_components.h_ipps_nat_nonlabor_shr = (1553.91).into();
    } else {
        state.hold_pps_components.h_ipps_nat_labor_shr = (3179.61).into();
        state.hold_pps_components.h_ipps_nat_nonlabor_shr = (1948.80).into();
    }
    if i64::from(state.wage_new_ipps_index_record.w_ipps_pr_wage_index) > 1i64 {
        state.hold_pps_components.h_ipps_pr_labor_shr = (1507.82).into();
        state.hold_pps_components.h_ipps_pr_nonlabor_shr = (924.15).into();
    } else {
        state.hold_pps_components.h_ipps_pr_labor_shr = (1427.57).into();
        state.hold_pps_components.h_ipps_pr_nonlabor_shr = (1004.40).into();
    }
}

